// ConnectionViewDto is `invoice.ConnectionViewDto`.
type ConnectionViewDto struct {
	// Mode The token’s mode.
	// Example: "live".
	Mode ConnectionViewDtoMode `json:"mode"`

	// Jurisdiction The organisation’s tax jurisdiction, ISO 3166-1 alpha-2; null when its country is not known.
	// Example: "NG".
	Jurisdiction *string `json:"jurisdiction"`

	// Kind Always `organization`: the connection is the organisation’s own.
	// Example: "organization".
	Kind ConnectionViewDtoKind `json:"kind"`

	// State `not_connected` (no connection in this mode), `awaiting_authority_listing` (waiting for the tax authority to list the business; no grant requested yet), `pending_taxpayer_enablement` (the taxpayer must act on the tax authority’s portal), `pending_grant_approval` (the grant waits on the access point provider’s side), `pending_key` (the grant is connected; the signing key must be uploaded), `connected` (live submissions pass), `suspended` (the grant went stale at the tax authority; `nextAction` says why) or `revoked` (disconnected).
	// Example: "connected".
	State ConnectionViewDtoState `json:"state"`

	// IssuesAs The identity a submission made now goes out under: `organisation`, or in sandbox `test_entity` until the organisation is connected.
	// Example: "organisation".
	IssuesAs ConnectionViewDtoIssuesAs `json:"issuesAs"`

	// Fallback The sandbox test entity while `issuesAs` is `test_entity`; null otherwise and always in live.
	Fallback *ConnectionFallbackDto `json:"fallback"`

	// TaxID The organisation’s own verified tax id the connection is for.
	// Example: "12345678-0001".
	TaxID *string `json:"taxId"`

	// TaxIDType The type of `taxId`.
	// Example: "tin".
	TaxIDType string `json:"taxIdType"`

	// AuthorityIdentifiers The identifiers the tax authority reports, shown once a connected grant showed them.
	AuthorityIdentifiers *AuthorityIdentifiersViewDto `json:"authorityIdentifiers"`

	// ClaimedIdentifiers The identifiers sent when connecting; null when none were.
	ClaimedIdentifiers *ClaimedIdentifiersViewDto `json:"claimedIdentifiers"`

	// NextAction What must happen next and who must act; null when nothing is needed.
	NextAction *ConnectionNextActionDto `json:"nextAction"`

	// Prerequisites What stands between the organisation and a connection, from its verified facts.
	Prerequisites ConnectionPrerequisitesViewDto `json:"prerequisites"`

	// Key The signing key with the access point, known by its certificate fingerprint only.
	Key ConnectionKeyDto `json:"key"`

	// AuthorityNextAction The tax authority gateway’s own guidance on what must happen next, relayed as the last check showed it; null when nothing is to do, before any check, and with no connection.
	AuthorityNextAction *AuthorityNextActionDto `json:"authorityNextAction"`

	// AuthorityLastCheckedAt When the gateway last checked the grant with the tax authority.
	// Example: "2026-11-14T08:00:00.000Z".
	AuthorityLastCheckedAt *string `json:"authorityLastCheckedAt"`

	// AuthorityNextCheckAt When the gateway will next check the grant; null when not scheduled or unknown.
	// Example: "2026-11-14T09:00:00.000Z".
	AuthorityNextCheckAt *string `json:"authorityNextCheckAt"`

	// SubmissionsAllowed Whether a live submission would be accepted now (true only while `connected`).
	// Example: true.
	SubmissionsAllowed bool `json:"submissionsAllowed"`

	// LastCheckedAt When Yona last read the grant from the tax authority gateway; null with no connection.
	// Example: "2026-11-14T08:01:00.000Z".
	LastCheckedAt *string `json:"lastCheckedAt"`

	// ConnectedAt When the connection became `connected`; null until it has.
	// Example: "2026-11-03T15:21:00.000Z".
	ConnectedAt *string `json:"connectedAt"`

	// DisconnectedAt When the connection was disconnected (`revoked`); null while it is live.
	DisconnectedAt *string `json:"disconnectedAt"`

	// History Every tax id the organisation’s grant was connected for in this mode, newest first; at most one open.
	History []TaxIdentityViewDto `json:"history"`

	// SharedWith The other mode whose connection shares this grant (disconnecting here then keeps it for that mode); null otherwise.
	SharedWith *ConnectionViewDtoSharedWith `json:"sharedWith"`

	// BusinessProfile The business the tax authority knows under this tax id, as the gateway relayed it (free-form, the authority’s fields); null until a check showed one, and with no connection.
	BusinessProfile map[string]any `json:"businessProfile"`

	// LegalNameMatches Whether that profile’s business name is the organisation’s verified legal name (case, spacing, punctuation and `LTD`/`LIMITED` ignored); null when either is unknown.
	// Example: true.
	LegalNameMatches *bool `json:"legalNameMatches"`

	// EinvoicingIdentifier The number the tax authority holds for the organisation on Yona’s access point — the live connection’s, else the first of the organisation’s numbers (its recorded TIN, then its verified tax id) the authority’s participant lookup finds. Null where identifier lookup is not enabled, without a verified tax id, or when none resolved (`identifierNextAction` says why).
	// Example: "1234567890123".
	EinvoicingIdentifier *string `json:"einvoicingIdentifier"`

	// IdentifierSource Where `einvoicingIdentifier` came from — `tin` (the e-invoicing TIN recorded beside the tax id) or `tax_id` (the verified tax id); null with no identifier.
	// Example: "tax_id".
	IdentifierSource *ConnectionViewDtoIdentifierSource `json:"identifierSource"`

	// IdentifierNextAction Why no number resolved — `add_tin` (no TIN recorded and the authority does not know the tax id), `enable_on_nrs` (the authority knows neither number), `choose_elyonar` (the authority lists the business with another access point provider), `retry` (the authority could not be asked). With no live connection it is also `nextAction.code`. Null when resolved, connected, or not computed; `?fresh=true` asks again.
	IdentifierNextAction *ConnectionViewDtoIdentifierNextAction `json:"identifierNextAction"`

	// ConnectWaits True when connecting now waits instead of being refused: `identifierNextAction` is `add_tin` or `enable_on_nrs` and this environment lets a business the tax authority does not list yet connect and wait (`state` becomes `awaiting_authority_listing`). False otherwise, including whenever `identifierNextAction` is null.
	// Example: false.
	ConnectWaits bool `json:"connectWaits"`

	// Listing While `state` is `awaiting_authority_listing` (the tax authority lists the business under none of its numbers yet, so no grant is requested), when it started waiting and when the authority is asked again; null in every other state.
	Listing *ListingViewDto `json:"listing"`
}

