// InvoiceLineItemDto is `invoice.InvoiceLineItemDto`.
type InvoiceLineItemDto struct {
	// ItemID A saved item of the organisation: every field of the line left out is filled from the item, and a field sent wins.
	// Example: "c56a4180-65aa-42ec-a945-5fd21dec0538".
	ItemID *string `json:"itemId,omitempty"`

	// Description Required without an itemId.
	// Example: "Consulting services".
	Description *string `json:"description,omitempty"`

	// ItemName The item’s name, sent to the tax authority as the line item’s name (the description is sent when absent).
	// Example: "Long grain parboiled rice, 50 kg".
	ItemName *string `json:"itemName,omitempty"`

	// HSNCode HS code (goods).
	// Example: "1006.30".
	HSNCode *string `json:"hsnCode,omitempty"`

	// ProductCategory The HS description (goods).
	// Example: "Semi-milled or wholly milled rice".
	ProductCategory *string `json:"productCategory,omitempty"`

	// ISICCode ISIC code (services); stored as the service code.
	// Example: "0112".
	ISICCode *string `json:"isicCode,omitempty"`

	// ServiceCategory The ISIC description (services). Stored as the line’s product category; send it or productCategory, not both.
	// Example: "Growing of rice".
	ServiceCategory *string `json:"serviceCategory,omitempty"`

	// Quantity Decimal string (≤ 6 decimals) or number; > 0.
	// Example: "2.5".
	Quantity Amount `json:"quantity"`

	// UnitCode A unit code of the jurisdiction’s list. Required without an itemId.
	// Example: "EA".
	UnitCode *string `json:"unitCode,omitempty"`

	// UnitPrice Major units, decimal string (≤ 4 decimals) or number; ≥ 0. Required without an itemId.
	// Example: "50000.00".
	UnitPrice *Amount `json:"unitPrice,omitempty"`

	// DiscountAmount Major units, ≤ 2 decimals.
	// Example: "0".
	DiscountAmount *Amount `json:"discountAmount,omitempty"`

	// FeeAmount Major units, ≤ 2 decimals.
	// Example: "0".
	FeeAmount *Amount `json:"feeAmount,omitempty"`

	// TaxCategory A tax-category code-list id, or a short alias (standard | zero | exempt). Required without an itemId.
	// Example: "STANDARD_VAT".
	TaxCategory *string `json:"taxCategory,omitempty"`
}

// InvoiceLineViewDto is `invoice.InvoiceLineViewDto`.
type InvoiceLineViewDto struct {
	// LineNo The line’s number, from 1.
	// Example: 1.
	LineNo int64 `json:"lineNo"`

	// Description What the line is for.
	// Example: "Ergonomic office chair, black".
	Description string `json:"description"`

	// ItemName The item’s name, sent to the tax authority as the line item’s name; null when none (the description is sent instead).
	// Example: "Ergonomic office chair".
	ItemName *string `json:"itemName"`

	// HSNCode HS code (goods); null when the line has none.
	// Example: "9401.30".
	HSNCode *string `json:"hsnCode"`

	// ProductCategory The description of the line’s code: the HS description (goods) or the ISIC description (services); null when none.
	// Example: "Swivel seats with variable height adjustment".
	ProductCategory *string `json:"productCategory"`

	// ServiceCode ISIC code (services); null when the line has none.
	// Example: "4649".
	ServiceCode *string `json:"serviceCode"`

	// UnitCode The unit code, from the jurisdiction’s list.
	// Example: "EA".
	UnitCode string `json:"unitCode"`

	// Quantity Exact decimal string.
	// Example: "2.000000".
	Quantity string `json:"quantity"`

	// UnitPrice Major units, exact decimal string.
	// Example: "50000.0000".
	UnitPrice string `json:"unitPrice"`

	// DiscountMinor The line discount. Integer minor units.
	// Example: 0.
	DiscountMinor int64 `json:"discountMinor"`

	// FeeMinor The line fee. Integer minor units.
	// Example: 0.
	FeeMinor int64 `json:"feeMinor"`

	// TaxCategory The tax category id the line was priced with.
	// Example: "STANDARD_VAT".
	TaxCategory string `json:"taxCategory"`

	// TaxRate Percent, decimal string.
	// Example: "7.5000".
	TaxRate string `json:"taxRate"`

	// LineNetMinor Quantity × unit price, less the discount, plus the fee. Integer minor units.
	// Example: 10000000.
	LineNetMinor int64 `json:"lineNetMinor"`

	// LineTaxMinor The tax on `lineNetMinor` at `taxRate`. Integer minor units.
	// Example: 750000.
	LineTaxMinor int64 `json:"lineTaxMinor"`

	// LineTotalMinor `lineNetMinor + lineTaxMinor`. Integer minor units.
	// Example: 10750000.
	LineTotalMinor int64 `json:"lineTotalMinor"`

	// ItemID The saved item the line was filled from.
	// Example: "c56a4180-65aa-42ec-a945-5fd21dec0538".
	ItemID *string `json:"itemId"`

	// CreditedQuantity On an invoice: the quantity credit notes have credited (what is left is `quantity − creditedQuantity`). Null on a note.
	// Example: "1.000000".
	CreditedQuantity *string `json:"creditedQuantity"`

	// CreditsLineNo On a credit-note line: the original invoice’s line it credits; null on an amount credit and elsewhere.
	// Example: 1.
	CreditsLineNo *int64 `json:"creditsLineNo"`
}

