// InvoiceReportingDto is `invoice.InvoiceReportingDto`.
type InvoiceReportingDto struct {
	// State How the document stands with the tax authority. `not_submitted`: a draft, never submitted, or its submission withdrawn; `in_progress`: submitted, waiting for the tax authority; `reported`: registered (also when the tax authority then could not transmit it); `rejected`: the tax authority rejected it; `on_hold`: its submission is on hold (see `nextAction`); `held`: issued while the connection to the tax authority was in progress; it is reported automatically once the connection completes.
	// Example: "reported".
	State InvoiceReportingDtoState `json:"state"`

	// Delivery How the buyer gets the document. `sent_email`: emailed to the buyer; `shared_link`: a share link was made; `deliver_to_buyer`: reported, and NRS will not deliver it (see `reason`), so send it yourself; `nrs`: reported and transmitted through NRS; `none`: none of these yet.
	// Example: "nrs".
	Delivery InvoiceReportingDtoDelivery `json:"delivery"`

	// DeliveredAt With `sent_email`, when it was emailed; with `shared_link`, when the first share link was made; null otherwise.
	// Example: "2026-11-14T09:30:00.000Z".
	DeliveredAt *string `json:"deliveredAt"`

	// Reason Why the document is delivered the way it is, when that needs saying. `buyer_off_network`: the buyer is not on NRS e-invoicing (or NRS could not transmit it after registering it); `b2c`: issued without a buyer TIN; `b2c_invalid_tin`: issued without the buyer’s TIN because it could not be used; `permission_withdrawn`: reported, then NRS refused to transmit it on permission grounds (invoice submission turned off for this access point); it is sent again once the connection is usable; `release_refused`: issued while the connection to the tax authority was in progress, and it could not be reported automatically once connected; report it from the invoice.
	// Example: "buyer_off_network".
	Reason *InvoiceReportingDtoReason `json:"reason"`

	// Irn The IRN once the tax authority registered the document (the same as `authorityReference`); null before.
	// Example: "YPLEKA26000042-F2D927D9-20260930".
	Irn *string `json:"irn"`

	// NextAction What the seller can do next (renumber and resubmit, or retry), when anything.
	// Example: "retry".
	NextAction *InvoiceReportingDtoNextAction `json:"nextAction"`

	// NextActionMessage With `renumber`, the sentence to show beside it; null otherwise.
	// Example: "This number is already used at the tax authority. Renumber and resubmit.".
	NextActionMessage *string `json:"nextActionMessage"`
}

